"""研究问题与判断规则。不是经济预测模型。"""
SYSTEMS = [
dict(code='K',name='需求与周期',school='凯恩斯主义',output='需求强弱、增长动力、复苏覆盖面及需求约束',horizon='月度变化与季度周期；年度核算补充结构',chain='收入与支出→订单与销售→生产与库存→就业、价格与利润',boundary='公开指标不能直接给出精确产出缺口或财政乘数；政府消费、财政支出与基建投资分别记录。',links='M融资转为支出；F偿债挤压支出；D收入分配影响消费',questions=[
('K1','支出能否消化生产能力？','有效需求相对供给偏弱时，销售、库存、产能利用、就业和价格出现相互印证的变化。','订单和销售弱，库存周转变慢、利用率下降，并有就业或价格证据。','销量、订单和利用率改善，库存下降，利润并未受损。','供给扩张、进口成本下降、结构性降价、春节错位和基数效应。','订单|PMI|消费|零售|产能|库存|价格|CPI|PPI|工业增加值|失业','只能描述需求压力，不能把PPI下降直接当作需求不足的因果证明。'),
('K2','消费、投资和外需谁在驱动变化？','支出结构变化解释增长来源，国民核算与高频代理提供不同频率的证据。','以同版三大需求拉动为起点，用住户消费、投资和贸易分项检验方向。','贡献上升仅由其他分项下降造成，或高频代理与年度核算方向相反。','净出口改善可能来自进口收缩；投资统计与资本形成口径不同。','GDP|生产总值|拉动|贡献|资本形成|消费|投资|出口|进口','海关顺差不等于GDP净出口贡献，社零不等于最终消费支出。'),
('K3','就业与价格是否支持需求改善？','广泛需求改善应逐步传导至劳动需求、居民收入及价格，但存在时滞和行业差异。','就业数量或工时、实际收入与服务价格等多个环节同向改善。','工业产出回升但工资、就业和居民消费未改善。','劳动供给变化、产业替代、成本冲击和调查样本变化。','就业|失业|工时|工作时间|收入|工资|核心|服务|居民消费','就业人口与城镇调查失业率的统计范围不同，不能直接相减求失业人数。'),
('K4','政府支出能否带动私人支出？','财政资金形成采购、转移或项目活动后，可能带动收入和私人支出；观察传导次序。','支出执行后，相关订单、居民消费或民间投资持续改善。','债券发行增加而支出执行、项目活动或私人投资没有接续。','共同政策冲击、项目周期、债务置换、财政存款变化。','财政|预算|政府性基金|转移|地方债|民间|投资|消费|资金来源','发债不等于当期新增财政需求，时间上的先后不单独证明带动效应。')]),
dict(code='M',name='货币与名义支出',school='货币主义及货币传导分析',output='货币环境、资金活跃程度及传导状况',horizon='月度货币与融资；季度及年度名义支出',chain='货币与存款结构→融资条件与融资结构→名义支出→价格与收入',boundary='流通速度是事后比率；公开数据不能确认每笔资金最终用途，也不能仅凭货币增速预测通胀。',links='K支出兑现；F债务周转和风险；D储蓄分布',questions=[
('M1','货币与名义经济如何变化？','货币存量与名义支出关系会受到持币行为、金融结构及统计口径变化影响。','比较可比货币增速、名义GDP与价格，区分长期关系和短期背离。','货币与名义增长背离由统计扩围或一次性存款迁移解释。','货币需求、金融深化、支付工具改变及口径修订。','M1|M2|货币|名义|生产总值|平减','不得把M2同比与GDP实际同比相减称作流通速度。'),
('M2','资金持有和使用行为是否改变？','活期、定期及不同部门存款变化为持币行为提供线索。','活期货币、部门存款结构与消费或交易活动方向一致。','存款变化源于部门间转移、理财回流或统计调整，支出并未变化。','存款替代、季末效应、财政收支时点。','M1|M2|存款|储蓄|消费|货币流通','新增住户存款不是住户储蓄流量，不能直接据此计算居民储蓄率。'),
('M3','融资价格、结构与支出是否一致？','融资成本变化要结合融资主体、期限及实际活动观察。','利率下降伴随企业或居民融资及相应投资消费改善。','融资增长集中于票据或政府债，私人支出弱；或利率下降但债务需求收缩。','贷款供给与需求同时变化、借新还旧、风险溢价和政策定向支持。','利率|LPR|融资|贷款|票据|投资|消费','名义利率减当期通胀只是事后近似，不命名为事前实际利率。'),
('M4','货币变化在哪个环节未转化为支出？','流动性、授信、融资取得、支出执行及收入形成是不同环节。','按货币→融资→支出→收入逐段对照并定位最先出现的背离。','所有阶段均改善却因使用不同时间或样本被误判为传导失败。','支出时滞、债务置换、财政与私人部门替代、数据发布滞后。','融资|贷款|存款|收入|利润|消费|投资|预算','只能定位候选阻滞环节，不能从汇总统计推断个体资金去向。')]),
dict(code='F',name='金融周期与资产负债表',school='金融周期及资产负债表分析',output='修复程度、融资压力及风险传导位置',horizon='季度负债与金融指标；月度地产和财政；年度债务决算',chain='资产价格与收入→债务及期限→偿付与再融资→金融机构和其他部门',boundary='地方隐性债务与完整居民偿债负担不自行估算；公开余额只支持负债规模判断。',links='K偿债与需求；M融资与再融资；S项目回报',questions=[
('F1','哪些部门在扩张或收缩负债？','负债变化需要同时考虑债务规模、部门结构以及名义收入分母。','贷款、债券或政府债务等同口径余额和净融资显示部门分化。','增速变化来自核销、证券化、统计调整或债务部门转移。','债务置换、融资工具替代、GDP修订。','债|贷款|融资|负债|净金融投资','不能将非金融企业、地方政府和城投债务简单相加，必须检查重叠。'),
('F2','收入和现金流能否支持债务？','相同债务规模下，现金流、付息负担和到期结构决定压力差异。','公开收入/利润/财政收支与付息或债务指标联合显示缓冲收窄。','利润变弱但现金回款改善，或期限延长和利息下降减轻当期压力。','债务展期、资产处置、财政转移、会计利润与现金流差异。','利润|营业收入|债务|利息|付息|财政|负债|偿债|回收|应收','政府债务/预算收入是压力代理，不是有统一阈值的违约概率。'),
('F3','资产价格如何影响偿债与融资？','地产价格、成交和回款变化可能影响抵押品、企业现金流及地方土地收入。','房价与成交、开发资金、土地收入和相关融资相互印证。','价格下降但成交回升、回款改善或现金缓冲充足。','住房结构变化、以价换量、土地供给节奏和项目交付。','房|商品房|土地|开发|待售|销售|按揭','成交均价受结构影响，不能等同于同质住房价格指数或抵押品价值。'),
('F4','风险如何跨部门传递？','地产和企业支付能力变化可能通过财政、贷款及金融机构损益传递。','债务/回款变化与相关财政或银行指标在匹配范围内同向变化。','银行指标改善由核销或分母扩张造成，或全国数据掩盖局部风险。','风险处置、会计确认时滞、监管口径及机构样本变化。','不良|拨备|资本充足|净息差|流动性|银行|预算|房地产','银行不良率下降不单独证明风险消失；无地域匹配数据不下城市银行结论。')]),
dict(code='G',name='要素与效率',school='新古典增长视角',output='可观察的长期增长支撑、效率变化及要素约束',horizon='年度结构为主，季度活动辅助',chain='人口与就业、教育与技能、投资与资本形成→产出和劳动生产率',boundary='不估算资本存量、潜在增速或TFP；劳动生产率变化也受到资本深化、工时和产业结构影响。',links='I技术扩散；S要素配置；D效率收益分配',questions=[
('G1','劳动力数量和质量如何变化？','劳动供给由人口结构、就业参与、健康、教育及技能共同影响。','劳动年龄人口、就业、教育与技能指标给出一致或分化的结构趋势。','人口下降但参与率、工时或人力资本改善抵消部分影响。','退休制度、迁移、教育扩张和调查口径差异。','人口|就业|教育|毕业|在校|学年|技能|寿命|抚养','在校生规模不是现有劳动力技能水平；不同年龄区间不得拼接。'),
('G2','投资与产出是否协调？','资本形成与产出、需求和利用率之间的关系提供投资效率线索。','投资扩张伴随产出、利用率和经营回报改善。','投资上升但利用率、销售和利润下降。','建设期滞后、公共品收益、产业周期和价格变化。','资本形成|投资|产能|营业收入|利润|增加值','固定资产投资不能作为资本存量，投资/新增GDP不直接称作资本回报率。'),
('G3','劳动生产率是否改善？','可比实际产出与匹配就业人数之比反映单位就业者产出。','同版本劳动生产率持续改善，并区分就业、产出与产业结构贡献线索。','改善来自就业分母缩减，或名义价格上涨而非实物效率。','资本深化、工时、行业构成和就业统计修订。','劳动生产率|生产总值|增加值|就业|工资','劳动生产率不等同TFP，不用名义GDP/就业冒充实际劳动生产率。'),
('G4','行业和地区有哪些效率差异？','相同统计口径下的产业、劳动与产出差异可支持结构性比较。','同口径地区/行业产出、就业与收入数据形成可重复的比较。','差异由价格、跨地区总部核算、工时和样本覆盖解释。','产业结构、公共服务与自然条件不同。','人均|地区|行业|产业|工资|投资|劳动生产率|收入','未经价格与样本控制不将地区人均GDP高低直接解释为技术效率。')]),
dict(code='I',name='创新与替代',school='熊彼特主义',output='创新转化程度、新增长动力及转型成本',horizon='年度投入产出与多年转化；季度产业活动辅助',chain='研发投入→创新成果→应用与扩散→经营表现→产业更替',boundary='专利、研发和新产业规模不是创新回报的充分证据；没有企业追踪数据时不证明创造性破坏的净效果。',links='G生产率；S产业条件；D就业收入分配',questions=[
('I1','创新投入是否形成成果？','研发投入通过有时滞且有失败风险的活动形成知识与技术成果。','研发资金/人员和高价值成果在匹配领域、合理时间窗口内共同改善。','研发扩张但成果质量、应用和市场表现未改善。','申请策略、补贴激励、研发周期和分类变化。','研发|研究|R&D|R＆D|专利|科技','不以当年研发除以当年授权专利简单衡量研发效率。'),
('I2','成果是否进入生产和市场？','知识成果经交易、应用、设备和流程扩散影响生产。','技术交易、新产品或高技术活动与应用端产出相互印证。','合同额增长但履约、销售或扩散证据不足。','合同口径、关联交易、进口设备及市场周期。','技术|新产品|高技术|装备|软件|数字|专利','技术合同成交额不等于当年研发成果收入，也不是已实现现金流。'),
('I3','新产业是否形成收入与回报？','创新必须结合需求与经营结果观察可持续性。','新产业增加值/收入增长，相关利润和利用率提供补充。','产量或销售扩张伴随降价、亏损或库存积压。','新进入企业前期投入、补贴、产品价格和统计范围。','高技术|新产品|战略|装备|软件|营业收入|利润|产能','公开行业总体利润不能归因到全部创新企业，不以规模增长证明投资回报。'),
('I4','新旧更替是否改善就业与效率？','新活动扩张与旧活动收缩可能带来就业重配及效率提升，也伴随转型成本。','新旧行业活动与就业/工资、生产率变化相互对应。','新产业增加但就业承接弱，旧产业退出或人员转岗证据不足。','企业注册与实际经营不同、外包、统计单位升降规。','产业|就业|工资|法人|企业|劳动生产率|高技术','缺少企业连续追踪时不测算净创造性破坏贡献。')]),
dict(code='S',name='产业与发展条件',school='新结构经济学',output='产业适配程度、升级路径及发展瓶颈',horizon='年度地区行业结构及项目周期',chain='要素条件→基础设施与公共服务→产业配置与关联→市场竞争力和回报',boundary='产业支持政策的因果效果不能由受支持行业增长单独确认；全国投入产出结构不能直接当作城市结构。',links='G要素与效率；I创新应用；F投资回报与债务',questions=[
('S1','产业结构是否适应当地要素条件？','产业对技能、资本、能源和市场的要求应与区域条件共同观察。','产业结构与技能/人口、能源、投资和市场数据可相互解释。','产能扩张与当地要素供给、销售和收入表现持续背离。','跨区要素流动、总部经济、资源禀赋及产业链分工。','产业|行业|投资|人口|教育|就业|工资|能源','不能仅凭产业占比指定某地应当发展或退出某个产业。'),
('S2','基础设施和公共服务有什么约束？','交通、能源和教育健康服务影响生产连接、劳动力及交易成本。','设施数量与实际使用、运输活动和公共服务指标联合呈现。','供给增加但利用不高，或总体充足仍有局部拥堵与短缺。','规模效应、人口密度、地理条件和利用口径。','交通|运输|货运|港口|铁路|公路|能源|电|教育|医保|卫生','里程、装机和财政支出是供给或投入，不能直接等同服务效率。'),
('S3','升级是否形成配套与市场？','产业升级需有投入来源、上下游联系及最终需求承接。','投入产出联系、工业分项和进出口结构提供匹配证据。','高技术占比上升但配套、订单或盈利证据弱。','价格、加工贸易、外需周期、再出口和分类重叠。','出口|进口|高技术|产业|工业|投入产出|增加值','技术产业分类与行业门类有重叠，不得相加为经济总量。'),
('S4','扩张是否伴随利用率和回报改善？','新增资本与产能应结合利用和经营结果检验可持续性。','相关投资、产能利用、销售和利润在合理项目期内同步改善。','投资持续上升而利用率、价格或利润承压。','学习期、公共品外部收益、替代旧产能和周期冲击。','投资|产能|收入|利润|库存|价格|开发','基建社会收益与企业财务收益不同，不能用工业利润率评价全部公共项目。')]),
dict(code='D',name='积累与分配',school='马克思主义政治经济学',output='积累与分配协调程度、群体差异及持续性约束',horizon='年度分配与再生产；季度住户、企业证据辅助',chain='生产与积累→利润和收入分配→消费与储蓄→再投资与再生产',boundary='理论中的剩余价值、利润率不能未经转换直接等同统计营业利润或工资占比；不以分组均值推算个体分布。',links='K有效需求；G生产率收益；I技术转型的分配后果',questions=[
('D1','资本积累与利润实现是否协调？','资本形成、生产扩张与销售和利润之间的关系体现再生产的经营约束。','积累扩张同时有收入、利润和库存周转支撑。','生产及投资增长而利润、回款和需求不足。','价格周期、会计变化、公共投资以及产业阶段差异。','资本形成|投资|利润|营业收入|库存|应收|储蓄','工业利润率不是马克思理论的一般利润率，不能跨口径套算。'),
('D2','劳动收入是否分享生产率改善？','生产率收益在劳动报酬、利润与其他收入间的分配影响增长的受益范围。','同范围实际工资/劳动报酬和劳动生产率在可比期间共同改善。','平均工资上涨但中位收入较弱，或就业覆盖收缩。','行业组成、自雇混合收入、税费与社保、就业单位样本。','工资|劳动者报酬|劳动报酬|劳动生产率|中位|收入','不能用城镇单位工资对全国劳动生产率直接推断劳动报酬份额变化。'),
('D3','分配如何影响消费能力？','不同收入群体的资源、负担和保障差异可能影响消费能力，但需要群体消费证据。','收入分组、城乡差异、消费和保障证据共同支持受益面判断。','收入分布变化却没有匹配群体消费数据。','生命周期、家庭规模、住房负担、资产与收入不同。','收入|消费|五等份|城乡|中位|保障|医保|养老|转移','无分组消费资料时不估算各收入组边际消费倾向；收入五等份不是财富五等份。'),
('D4','生产、消费和再投资有哪些张力？','部门收入、储蓄与资本形成联系揭示资金余缺及支出衔接。','以资金流量账户连接部门分配、储蓄、投资与净金融投资。','现象依赖错误加总、表间版本不一或将存款增加当作储蓄。','对外收支、资本转移、其他非金融资产和统计差异。','可支配总收入|初次分配|储蓄|净金融投资|资本形成|实际最终消费|经常|部门','部门余额关系是核算联系，不是因果关系；统计差额保留，不强制配平。')])
]

GLOBAL_RULES = [
('R01','事实与解释','先写数据事实、来源和范围，再写机制解释；条件推论与观察事实分列。','相关性或时间顺序不独立证明因果。'),
('R02','证据充分程度','证据充分程度用“多环节支持、部分支持、相互矛盾、证据不足”；各问题至少检查一个结果环节和一个机制环节，并列反向证据。','这是研究记录规范，不是统计显著性或危机概率。'),
('R03','共享证据','同一序列、同一调查样本、由同一原值派生的指标归入共享证据组；在七套体系中重复使用不增加独立证据数量。','同源指标共同变动可能源于相同统计误差。'),
('R04','时间与版本','报告期、发布日期和本次读取日期分开；同一比较采用同版修订序列。低频值记录原报告期，不插值成为实际月度观测。','已修订数据不能冒充历史时点当时已知数据。'),
('R05','范围与比率','分子分母需匹配币种、期间、地域、样本、部门和价格口径。存量/年度流量比率标明含义，不命名为偿债率。','区分省全域、地市全域、市辖区和市本级财政。'),
('R06','缺失与零','原文空缺、未披露、抓取失败、口径不可比和不适用分别登记；有效零值保留。缺输入时派生结果为空并记录原因。','不把数据缺口解释为经济活动不存在。'),
('R07','同比与累计','不相减累计增速得到当月增速；只有可比累计金额才可作差，且保留春节合并月、样本调整和自产自用等限制。','基数效应与季节性必须检验。'),
('R08','多层次覆盖','总体分组与交叉分组分别核验；分类目录完整不等于每个组合有数据；明示已覆盖、部分覆盖、无稳定公开数据和不适用。','无稳定公开数据仅指截至核验日未取得适用公开序列，并非断言不存在。'),
('R09','全景分歧','按统计口径→报告期与时滞→行业/群体→竞争解释顺序排查；仍不一致就保留分歧和下一条判别证据。','不投票、不将七套结论加权成经济健康总分。'),
('R10','阈值与情景','只有公开明确界限可直接引用，例如PMI的50；历史位置仅在连续可比区间计算。政策含义以条件句表达。','不编造红黄绿危机阈值，不把同比转正等同经济健康。'),
('R11','核算恒等关系','只在同版同口径表内核对；国际收支统计差额、地区与全国核算差异分别记录。','不强制省级GDP之和等于全国GDP。'),
('R12','替代变量','每个代理都写明能观察什么、不能观察什么；不将劳动生产率升级为TFP、专利量升级为回报、余额升级为偿债能力。','缺少可观测变量时缩小结论范围，不扩大代理的含义。')
]
